    if (!raw || typeof raw !== "object") return config;

    // 保全异构/未知 schema 原始配置
    if (raw.schemaVersion !== ENHANCEMENT_SETTINGS_SCHEMA_VERSION) {
      config._unsupportedSchemaVersion = raw.schemaVersion;
      config._rawUnsupportedConfig = raw;
    }

    // 保全未知 modules
